package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.persistence.mapper.*;
import java.io.IOException;
import java.time.*;
import java.util.*;

/** Factual connection qualification only. No worker, token, dispatch or invocation-service
 * dependency: the complete original ledger and actual settled result remain mandatory. */
public final class ConnectionVerificationPassedAuthority {
 private final ConnectionVerificationMapper mapper;private final PermissionMapper permissions;
 private final ModelConfigurationService models;private final ApprovedCredentialAuthority credentials;
 private final FormalInvocationStarts starts;private final FormalInvocationCompleted completed;
 private final ConnectionVerificationSchema schema;private final PermissionSchema json;private final long maximumAgeSeconds;
 public ConnectionVerificationPassedAuthority(ConnectionVerificationMapper mapper,PermissionMapper permissions,ModelConfigurationService models,ApprovedCredentialAuthority credentials,FormalInvocationStarts starts,FormalInvocationCompleted completed,ConnectionVerificationSchema schema,PermissionSchema json,long maximumAgeSeconds){
  this.mapper=Objects.requireNonNull(mapper);this.permissions=Objects.requireNonNull(permissions);this.models=Objects.requireNonNull(models);this.credentials=Objects.requireNonNull(credentials);this.starts=Objects.requireNonNull(starts);this.completed=Objects.requireNonNull(completed);this.schema=Objects.requireNonNull(schema);this.json=Objects.requireNonNull(json);if(maximumAgeSeconds<=0)throw new IllegalArgumentException("Explicit connection proof age required");this.maximumAgeSeconds=maximumAgeSeconds;
 }
 public final class Passed {
  private final EnterpriseAccess.Admission admission;private final String verification,model,purpose,project,digest,price;
  private Passed(EnterpriseAccess.Admission a,String verification,String model,String purpose,String project,String digest,String price){this.admission=a;this.verification=verification;this.model=model;this.purpose=purpose;this.project=project;this.digest=digest;this.price=price;}
  public String priceVersion(){return price;}public void requireUnchanged()throws IOException{if(!digest.equals(requirePassed(admission,verification,model,purpose,project).digest))throw new TenantAccessException(ErrorCode.SCOPE_STALE);}
 }
 public Passed requirePassed(EnterpriseAccess.Admission a,String verification,String model,String purpose,String project)throws IOException{
  var i=single(mapper.intent(parameters("verificationId",verification)));var fixed=models.requireCurrentExternal(a,model,purpose,project);var d=(ModelConfigurationProtocol.Definition)fixed.definition();requireSupportedOwner(fixed,i.projectId());
  if(!i.tenantId().equals(a.context().tenant_id())||!i.verificationId().equals(verification)||!i.modelRevision().equals(model)||!i.configId().equals(fixed.config_id())||!i.modelHash().equals(hash(fixed))||!i.credentialReferenceId().equals(d.credential_reference_id())||!i.credentialRevision().equals(d.credential_revision())||!"1.0.0".equals(i.schemaVersion())||!schema.manifest().equals(i.manifest())||!hash(schema.request(i.requestJson().getBytes(java.nio.charset.StandardCharsets.UTF_8))).equals(i.requestHash()))fail();
  credentials.require(a.context().tenant_id(),d.credential_reference_id(),d.credential_revision(),d.provider(),d.base_url()).requireCurrent();verifyLedger(i);var completed=single(mapper.completed(parameters("verificationId",verification)));if(!completed.invocationId().equals(requireBinding(a,i,false)))fail();var settled=completed(a,completed.invocationId(),verification);var checkedAt=permissions.databaseTime().toInstant(ZoneOffset.UTC);var verifiedAt=settled.verifiedAt();if(verifiedAt.isBefore(Instant.parse(i.createdAt()))||settled.settledAt().isBefore(verifiedAt)||settled.settledAt().isAfter(Instant.parse(completed.createdAt())))fail();if(verifiedAt.isAfter(checkedAt)||!checkedAt.isBefore(verifiedAt.plusSeconds(maximumAgeSeconds)))throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
  if(!"1.0.0".equals(completed.schemaVersion())||!Objects.equals(completed.projectId(),i.projectId())||!completed.tenantId().equals(i.tenantId())||!completed.verificationId().equals(verification)||!completed.createdBy().equals(i.actorId())||!completed.manifest().equals(i.manifest())||!completed.classification().equals(i.classification())||!completed.receiptHash().equals(settled.receiptSha256())||!schemaRead(completed.artifactJson()).equals(json.tree(settled.receiptArtifact()))||!completed.priceVersion().equals(settled.priceVersion())||!completed.currency().equals(settled.currency())||!completed.settledAmount().equals(settled.settledAmount().toString())||!completed.usageReceiptId().equals(settled.usageReceiptId())||!d.price_basis().version_id().equals(settled.priceVersion())||!d.currency().equals(settled.currency()))fail();
  var v=values(i);v.put("auditId",completed.auditId());v.put("eventId",completed.eventId());var original=schemaRead(single(mapper.operation(v)));var receipt=completionReceipt(i,completed);
  if(!original.required("state").asText().equals("COMPLETED")||original.required("http_status").intValue()!=200||!original.required("response_ref").equals(receipt)||!schemaRead(single(mapper.audit(v))).equals(completedWitness(completed,receipt))||!schemaRead(single(mapper.event(v))).equals(completedWitness(completed,receipt)))fail();
  var base=schemaRead(single(mapper.verification(v)));verifyBase(i,base);if(!Objects.equals(nullable(base.required("project_id")),fixed.project_id()))fail();if(!"PASSED".equals(base.required("status").textValue())||!"3".equals(base.required("revision").textValue())||!base.required("receipt_ref").equals(json.tree(settled.receiptArtifact()))||!base.required("receipt_artifact_id").textValue().equals(settled.receiptArtifact().artifactId())||!base.required("endpoint_identity").textValue().equals(d.base_url())||!Instant.parse(base.required("verified_at").textValue()).equals(settled.verifiedAt()))fail();
  return new Passed(a,verification,model,purpose,project,hash(Map.of("intent",i,"completed",completed,"base",base)),settled.priceVersion());
 }
 String requireBinding(EnterpriseAccess.Admission a,ConnectionVerificationMapper.Intent intent,boolean ownerOnly)throws IOException{
  var b=single(mapper.binding(parameters("verificationId",intent.verificationId())));var start=(ownerOnly?starts.readVerificationStart(a,intent.verificationId()):starts.readAuthorizedVerificationStart(a,intent.verificationId())).orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));if(!"1.0.0".equals(b.schemaVersion())||!Objects.equals(b.projectId(),intent.projectId())||!b.tenantId().equals(intent.tenantId())||!b.verificationId().equals(intent.verificationId())||!b.createdBy().equals(intent.actorId())||!b.classification().equals(intent.classification())||Instant.parse(b.createdAt()).isBefore(Instant.parse(intent.createdAt()))||Instant.parse(b.createdAt()).isAfter(permissions.databaseTime().toInstant(ZoneOffset.UTC))||!start.verificationId().equals(intent.verificationId())||!start.requestBodySha256().equals(intent.requestHash())||!start.modelRevision().equals(intent.modelRevision())||!start.credentialReferenceId().equals(intent.credentialReferenceId())||!start.credentialRevision().equals(intent.credentialRevision())||!b.requestHash().equals(intent.requestHash())||!b.modelRevision().equals(intent.modelRevision())||!b.credentialReferenceId().equals(intent.credentialReferenceId())||!b.credentialRevision().equals(intent.credentialRevision())||b.invocationId()!=null||!b.runId().equals(start.runId())||!b.stepId().equals(start.stepId())||!b.actionId().equals(start.actionId())||!b.inputHash().equals(start.inputSha256())||!schema.manifest().equals(b.manifest())||!schemaRead(b.receiptJson()).equals(startReceipt(intent,null)))fail();return start.invocationId();
 }
 private static void requireSupportedOwner(ModelConfigurationProtocol.Fixed fixed,String project){if(project==null||fixed.project_id()==null||!project.equals(fixed.project_id()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);if(!((ModelConfigurationProtocol.Definition)fixed.definition()).provider().equals("DEEPSEEK"))throw new TenantAccessException(ErrorCode.MODEL_POLICY_INCOMPLETE);}
 private static Map<String,Object> parameters(String key,Object value){return Map.of("userId",TenantScope.requireCurrent().subjectId(),key,value);}
 private static Map<String,Object> values(ConnectionVerificationMapper.Intent r){var v=new HashMap<String,Object>();v.put("userId",TenantScope.requireCurrent().subjectId());v.put("actorId",r.actorId());v.put("projectId",r.projectId());v.put("verificationId",r.verificationId());v.put("modelRevision",r.modelRevision());v.put("configId",r.configId());v.put("credentialReferenceId",r.credentialReferenceId());v.put("credentialRevision",r.credentialRevision());v.put("requestHash",r.requestHash());v.put("key",r.key());v.put("operationId",r.operationId());v.put("manifest",r.manifest());v.put("classification",r.classification());return v;}
 JsonNode completionReceipt(ConnectionVerificationMapper.Intent i,ConnectionVerificationMapper.Completed c){var result=json.object();result.put("schema_version","1.0.0");result.put("verification_id",i.verificationId());result.put("operation_id",i.operationId());result.put("request_body_sha256",i.requestHash());result.put("status","PASSED");result.put("invocation_id",c.invocationId());result.put("receipt_sha256",c.receiptHash());return result;}
 private void verifyBase(ConnectionVerificationMapper.Intent i,JsonNode base){if(!i.verificationId().equals(base.required("verification_id").textValue())||!i.configId().equals(base.required("config_id").textValue())||!i.modelRevision().equals(base.required("model_revision").textValue())||!i.credentialReferenceId().equals(base.required("credential_reference_id").textValue())||!i.credentialRevision().equals(base.required("credential_revision").textValue())||!i.actorId().equals(base.required("created_by").textValue())||!i.manifest().equals(base.required("schema_manifest_sha256").textValue())||!"1.0.0".equals(base.required("schema_version").textValue())||!i.classification().equals(base.required("classification").textValue())||!base.required("error_code").isNull()||!"MODEL".equals(base.required("configuration_kind").textValue())||!Instant.parse(i.createdAt()).equals(Instant.parse(base.required("created_at").textValue())))fail();}
 JsonNode intentWitness(ConnectionVerificationMapper.Intent i)throws IOException{var n=(com.fasterxml.jackson.databind.node.ObjectNode)json.tree(i);n.put("request_json",canonical(schemaRead(i.requestJson())));n.put("created_at",Instant.parse(i.createdAt()).toString());return json.tree(Map.of("schema_version","1.0.0","verification_id",i.verificationId(),"intent_sha256",hash(n)));}
 JsonNode completedWitness(ConnectionVerificationMapper.Completed c,JsonNode receipt)throws IOException{var n=(com.fasterxml.jackson.databind.node.ObjectNode)json.tree(c);n.put("artifact_json",canonical(schemaRead(c.artifactJson())));n.put("created_at",Instant.parse(c.createdAt()).toString());return json.tree(Map.of("schema_version","1.0.0","receipt",receipt,"completed_sha256",hash(n)));}
 void verifyLedger(ConnectionVerificationMapper.Intent intent)throws IOException{
  RuntimeGovernanceSchema.key(intent.key());var v=values(intent);v.put("auditId",intent.auditId());v.put("eventId",intent.eventId());var anchor=intentWitness(intent);if(!schemaRead(single(mapper.intentAudit(v))).equals(anchor)||!schemaRead(single(mapper.intentEvent(v))).equals(anchor))fail();var base=schemaRead(single(mapper.verification(v)));verifyBase(intent,base);var op=schemaRead(single(mapper.operation(v)));if(!op.required("error_code").isNull()||!Instant.parse(intent.createdAt()).equals(Instant.parse(op.required("created_at").textValue())))fail();
  var bindings=mapper.binding(parameters("verificationId",intent.verificationId()));var completions=mapper.completed(parameters("verificationId",intent.verificationId()));if(bindings.size()>1||completions.size()>1)fail();
  if("PROCESSING".equals(op.required("state").textValue())){if(!op.required("http_status").isNull()||!"1".equals(op.required("revision").textValue())||!op.required("response_ref").equals(schemaRead(intent.requestJson()))||!Instant.parse(op.required("updated_at").textValue()).equals(Instant.parse(intent.createdAt()))||!completions.isEmpty()||!base.required("receipt_ref").isNull()||!base.required("receipt_artifact_id").isNull()||!base.required("endpoint_identity").isNull()||!base.required("verified_at").isNull())fail();
   if(bindings.isEmpty()){if(!"PENDING".equals(base.required("status").textValue())||!"1".equals(base.required("revision").textValue())||!Instant.parse(base.required("updated_at").textValue()).equals(Instant.parse(intent.createdAt())))fail();}
   else if(!"RUNNING".equals(base.required("status").textValue())||!"2".equals(base.required("revision").textValue())||!Instant.parse(base.required("updated_at").textValue()).equals(Instant.parse(bindings.get(0).createdAt())))fail();
  }else if("COMPLETED".equals(op.required("state").textValue())){if(bindings.size()!=1||completions.size()!=1)fail();var done=completions.get(0);if(!"2".equals(op.required("revision").textValue())||op.required("http_status").intValue()!=200||!op.required("response_ref").equals(completionReceipt(intent,done))||!Instant.parse(op.required("updated_at").textValue()).equals(Instant.parse(done.createdAt()))||!Instant.parse(base.required("updated_at").textValue()).equals(Instant.parse(done.createdAt()))||Instant.parse(done.createdAt()).isBefore(Instant.parse(bindings.get(0).createdAt()))||!"PASSED".equals(base.required("status").textValue())||!"3".equals(base.required("revision").textValue()))fail();}
  else fail();
 }
 private JsonNode startReceipt(ConnectionVerificationMapper.Intent i,String invocation){var n=json.object();n.put("schema_version","1.0.0");n.put("verification_id",i.verificationId());n.put("operation_id",i.operationId());n.put("invocation_id",invocation);n.put("request_body_sha256",i.requestHash());n.put("status","RUNNING");return n;}
 private JsonNode schemaRead(String value)throws IOException{return schema.read(value);}
 private String canonical(Object value)throws IOException{return new String(ContentReadAuthorization.canonicalBytes(value),java.nio.charset.StandardCharsets.UTF_8);}
 private String hash(Object value)throws IOException{return org.apache.commons.codec.digest.DigestUtils.sha256Hex(ContentReadAuthorization.canonicalBytes(value));}
 private static String nullable(JsonNode n){return n.isNull()?null:n.textValue();}
 private static <T>T single(List<T> rows){if(rows.size()!=1)fail();return Objects.requireNonNull(rows.get(0));}
 private static void fail(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
 private FormalInvocationCompleted.SettledProof completed(EnterpriseAccess.Admission a,String invocation,String verification)throws IOException{try{return completed.require(a,invocation,verification);}catch(IOException e){throw e;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IOException("Formal invocation evidence unavailable",e);}}
}
